={{ JSON.stringify((() => {
  const T = v => [{ text: { content: String(v).slice(0, 1900) } }];
  const pick = (v, list) => list.includes(String(v || '').trim()) ? { select: { name: String(v).trim() } } : null;
  const num = v => (Number(v) > 0 ? { number: Number(v) } : null);
  const txt = v => (String(v || '').trim() ? { rich_text: T(v) } : null);
  const p = {
    'Name': { title: T($fromAI('name', 'عنوان قصير للسجل، مثل: طلب مكتب ١٠ أشخاص — العليا', 'string')) },
    'Record Type': pick($fromAI('record_type', 'واحد فقط: Demand - Client Request أو Supply - For Rent أو Supply - For Sale', 'string'), ['Demand - Client Request', 'Supply - For Rent', 'Supply - For Sale']),
    'Status': { select: { name: 'New' } },
    'City': pick($fromAI('city', 'Riyadh أو Jeddah أو Dammam أو Khobar أو Makkah أو Madinah أو Other — فارغ إن لم يُذكر', 'string'), ['Riyadh', 'Jeddah', 'Dammam', 'Khobar', 'Makkah', 'Madinah', 'Other']),
    'Property Category': pick($fromAI('category', 'Office أو Co-working Space أو Commercial أو Retail أو Showroom أو Industrial أو Land أو Residential أو Labor Camp أو Compound أو Mixed-use أو Hospitality أو Workshop أو Factory أو Building أو Other', 'string'), ['Residential', 'Commercial', 'Office', 'Co-working Space', 'Retail', 'Showroom', 'Industrial', 'Land', 'Labor Camp', 'Compound', 'Mixed-use', 'Hospitality', 'Workshop', 'Factory', 'Building', 'Other']),
    'Channel Source': pick($fromAI('channel', 'Web Form أو Email أو WhatsApp أو LinkedIn أو Social Media أو Manual', 'string'), ['Web Form', 'Email', 'WhatsApp', 'LinkedIn', 'Social Media', 'Manual']),
    'Budget / Price': num($fromAI('budget', 'الميزانية أو السعر بالريال كما ذُكر حرفياً، 0 إن لم يُذكر — لا تقدّر', 'number')),
    'Size sqm': num($fromAI('size_sqm', 'المساحة بالمتر كما ذُكرت، 0 إن لم تُذكر', 'number')),
    'Seats / Capacity': num($fromAI('seats', 'عدد المقاعد أو الأشخاص كما ذُكر، 0 إن لم يُذكر', 'number')),
    'District': txt($fromAI('district', 'الحي إن ذُكر، وإلا فارغ', 'string')),
    'Contact Person': txt($fromAI('contact_person', 'اسم جهة التواصل إن ذُكر، وإلا فارغ', 'string')),
    'AI Summary': txt($fromAI('summary', 'ملخص الطلب أو العرض بالحقائق التي وردت فقط', 'string')),
    'Next Action': txt($fromAI('next_action', 'الخطوة التالية بالضبط', 'string')),
    'مصدر السجل': { rich_text: T('Tariq — BP AI') }
  };
  const ph = String($fromAI('phone', 'رقم الجوال بصيغة دولية إن ذُكر، وإلا فارغ', 'string') || '').trim();
  if (ph) p['Phone'] = { phone_number: ph };
  const em = String($fromAI('email', 'البريد إن ذُكر، وإلا فارغ', 'string') || '').trim();
  if (/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(em)) p['Email'] = { email: em };
  Object.keys(p).forEach(k => { if (p[k] === null) delete p[k]; });
  return { parent: { data_source_id: 'c190c41b-acb4-48f2-b0e6-a004b1221d86' }, properties: p };
})()) }}

={{ JSON.stringify((() => {
  const T = v => [{ text: { content: String(v).slice(0, 1900) } }];
  const txt = v => (String(v || '').trim() ? { rich_text: T(v) } : null);
  const SELF = ['New', 'Need Verification', 'Matching', 'Matched', 'RFQ Draft', 'Waiting Quote', 'Quote Received', 'Available', 'Archived'];
  const HUMAN = ['Approved for RFQ', 'RFQ Sent', 'Proposal Sent', 'Closed Won', 'Closed Lost'];
  const SCORES = ['Excellent', 'Good', 'Fair', 'Poor', 'No Match'];
  const st = String($fromAI('status', 'الحالة الجديدة: New أو Need Verification أو Matching أو Matched أو RFQ Draft أو Waiting Quote أو Quote Received أو Available أو Archived. فارغ لعدم التغيير. Approved for RFQ وRFQ Sent وProposal Sent وClosed Won/Lost بوابات بشرية ولن تُكتب', 'string') || '').trim();
  const sc = String($fromAI('match_score', 'Excellent أو Good أو Fair أو Poor أو No Match حسب معايير المطابقة، فارغ إن لم تُطابق', 'string') || '').trim();
  const p = {
    'Match Notes': txt($fromAI('match_notes', 'سبب المطابقة أو عدمها: المدينة، الفئة، المساحة، الميزانية — من بيانات البورد فقط', 'string')),
    'Next Action': txt($fromAI('next_action', 'الخطوة التالية بالضبط', 'string')),
    'Proposal / RFQ Message': txt($fromAI('rfq_message', 'مسودة RFQ للمورد أو العرض للعميل إن جهّزتها — مسودة فقط بانتظار الموافقة، وإلا فارغ', 'string')),
    'Last Match Run': { date: { start: new Date().toISOString() } }
  };
  if (SELF.includes(st)) p['Status'] = { select: { name: st } };
  if (HUMAN.includes(st) || p['Proposal / RFQ Message']) p['Approval Status'] = { select: { name: 'Awaiting BP Approval' } };
  if (SCORES.includes(sc)) { p['Match Score'] = { select: { name: sc } }; p['Match Status'] = { select: { name: sc } }; }
  Object.keys(p).forEach(k => { if (p[k] === null) delete p[k]; });
  return { properties: p };
})()) }}
